import * as React from "react"
import { AD_SIZES, AD_TEMPLATES, AD_TRADES, QR_SLOT, adPalette, fill, sizeById, templateById, trackedUrl } from "../../lib/ad-templates"
import { drawAd, defaultQrRect } from "../../lib/ad-canvas"
import { loadImage, makeQrImage } from "../../lib/qr-image"
import { useAuth } from "../../context/auth"
import { apiUrl } from "../../config/api"
import { THEMES } from "../../lib/site-draft"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"

/**
 * The ad studio — MTC-FCS-037 / 040 / 041.
 * ============================================================================
 * A marketer picks a template, gets a QR that carries their own id, drags it
 * where they want it, and downloads a PNG to drop into a Facebook group.
 *
 * ── TWO CANVASES, ON PURPOSE ───────────────────────────────────────────────
 * The one on screen carries the drag outline; the export draws the same advert
 * into a fresh canvas with no outline at all. Drawing the handles into the
 * artwork is the classic way a tool like this ships a selection box on a
 * customer's advert.
 *
 * ── THE CANVAS IS ALWAYS 1080 WIDE ─────────────────────────────────────────
 * However small it is displayed. Pointer positions are scaled into canvas
 * space, so dragging on a 380px preview positions the code correctly on the
 * 1080px image — and the download is full size rather than a screenshot.
 *
 * ── NOTHING LEAVES THE BROWSER TO MAKE THE IMAGE ───────────────────────────
 * The composition is all client side. The one server call is registering the
 * id (MTC-FCS-041), which is about tracking rather than about the picture.
 */

const PRICE_OPTIONS = ["$15", "$19.99", "$24.98"]

const AdStudio = ({ styles: s }) => {
  const canvasRef = React.useRef(null)
  const photoRef = React.useRef(null)
  const qrRef = React.useRef(null)
  const dragRef = React.useRef(null)
  // Where the renderer put the QR when nobody has dragged it yet.
  const autoRef = React.useRef(null)

  const [templateId, setTemplateId] = React.useState(AD_TEMPLATES[0].id)

  /* Which palette this advert is drawn in — FCS-069. The website builder's
     own six, so an ad and the site it sells look like one company, and so a
     marketer posting into six groups is not posting the same picture six
     times. */
  const [themeId, setThemeId] = React.useState(THEMES[0].id)
  const [sizeId, setSizeId] = React.useState(AD_SIZES[0].id)
  const [tradeSlug, setTradeSlug] = React.useState(AD_TRADES[0].slug)
  const [price, setPrice] = React.useState(PRICE_OPTIONS[0])
  const [code, setCode] = React.useState("")
  const [placedIn, setPlacedIn] = React.useState("")
  const [headline, setHeadline] = React.useState("")
  const [sub, setSub] = React.useState("")

  const [qrRect, setQrRect] = React.useState(null)
  const [qrScale, setQrScale] = React.useState(1)
  const [dragging, setDragging] = React.useState(false)
  const [status, setStatus] = React.useState(null)
  const [origin, setOrigin] = React.useState("https://freecontractorservices.com")
  // Who the code belongs to. The report is scoped by this, so a code saved
  // while signed out belongs to nobody and shows up in no report.
  const { user } = useAuth()

  const template = templateById(templateId)
  const size = sizeById(sizeId)
  const trade = AD_TRADES.find(t => t.slug === tradeSlug) || AD_TRADES[0]
  const link = trackedUrl(origin, code)

  React.useEffect(() => {
    if (typeof window !== "undefined") setOrigin(window.location.origin)
  }, [])

  /* ── Draw ──────────────────────────────────────────────────────────── */
  const paint = React.useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    canvas.width = size.width
    canvas.height = size.height
    const ctx = canvas.getContext("2d")

    const placed = drawAd(ctx, {
      template,
      colours: adPalette(themeId),
      size,
      trade: trade.word,
      price,
      headline: headline || template.headline,
      sub: sub || template.sub,
      photo: photoRef.current,
      qr: qrRef.current,
      qrRect: qrRect || undefined,
    })

    const rect = placed.qrRect
    autoRef.current = rect

    // The outline lives on the PREVIEW only — never in the export.
    if (qrRef.current) {
      ctx.save()
      ctx.strokeStyle = "rgba(22, 104, 232, 0.9)"
      ctx.setLineDash([10, 8])
      ctx.lineWidth = 4
      ctx.strokeRect(rect.x - 6, rect.y - 6, rect.size + 12, rect.size + 12)
      ctx.restore()
    }
  }, [template, size, trade, price, headline, sub, qrRect])

  /* Fonts first: drawing before Poppins has loaded measures Arial and wraps
     the headline in the wrong place. */
  React.useEffect(() => {
    let cancelled = false
    const run = async () => {
      if (typeof document !== "undefined" && document.fonts?.ready) {
        await document.fonts.ready.catch(() => {})
      }
      photoRef.current = await loadImage(`/ads/${trade.image}`)
      if (!cancelled) paint()
    }
    run()
    return () => {
      cancelled = true
    }
  }, [trade, paint])

  React.useEffect(() => {
    paint()
  }, [paint])

  /* Changing size resets the slot, because a position from a 4:5 canvas is in
     the wrong place on a square one. */
  React.useEffect(() => {
    setQrRect(null)
    setQrScale(1)
  }, [sizeId])

  /* ── The QR ────────────────────────────────────────────────────────── */
  const makeQr = async () => {
    setStatus({ kind: "busy", text: "Making the code…" })
    try {
      const img = await makeQrImage(link, 1024)
      qrRef.current = img
      // Leave the position to the renderer unless it has been dragged.
      setQrRect(prev => prev)
      setStatus({ kind: "ok", text: `Code points at ${link}` })
      paint()
    } catch (err) {
      setStatus({ kind: "error", text: `Could not make the code: ${err.message}` })
    }
  }

  const resize = value => {
    const scale = Number(value)
    setQrScale(scale)
    const base = autoRef.current || defaultQrRect(size.width, size.height)
    setQrRect(prev => {
      const current = prev || base
      const next = Math.max(QR_SLOT.minPixels * 0.7, base.size * scale)
      // Grow from the centre so the code does not walk across the page.
      return {
        x: Math.min(Math.max(0, current.x + (current.size - next) / 2), size.width - next),
        y: Math.min(Math.max(0, current.y + (current.size - next) / 2), size.height - next),
        size: next,
      }
    })
  }

  /* ── Dragging ──────────────────────────────────────────────────────── */
  const pointFrom = event => {
    const canvas = canvasRef.current
    const box = canvas.getBoundingClientRect()
    // The displayed canvas is smaller than the real one; scale into its space.
    return {
      x: ((event.clientX - box.left) * canvas.width) / box.width,
      y: ((event.clientY - box.top) * canvas.height) / box.height,
    }
  }

  const onPointerDown = event => {
    if (!qrRef.current) return
    const rect = qrRect || autoRef.current || defaultQrRect(size.width, size.height)
    const point = pointFrom(event)
    const inside =
      point.x >= rect.x &&
      point.x <= rect.x + rect.size &&
      point.y >= rect.y &&
      point.y <= rect.y + rect.size
    if (!inside) return

    dragRef.current = { dx: point.x - rect.x, dy: point.y - rect.y }
    setDragging(true)
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  const onPointerMove = event => {
    if (!dragRef.current) return
    const rect = qrRect || autoRef.current || defaultQrRect(size.width, size.height)
    const point = pointFrom(event)
    setQrRect({
      size: rect.size,
      // Clamped, so the code cannot be dragged off the edge and silently lost.
      x: Math.min(Math.max(0, point.x - dragRef.current.dx), size.width - rect.size),
      y: Math.min(Math.max(0, point.y - dragRef.current.dy), size.height - rect.size),
    })
  }

  const endDrag = event => {
    dragRef.current = null
    setDragging(false)
    try {
      event.currentTarget.releasePointerCapture(event.pointerId)
    } catch {
      /* already released */
    }
  }

  /* ── Export ────────────────────────────────────────────────────────── */
  const download = () => {
    const out = document.createElement("canvas")
    out.width = size.width
    out.height = size.height
    drawAd(out.getContext("2d"), {
      template,
      colours: adPalette(themeId),
      size,
      trade: trade.word,
      price,
      headline: headline || template.headline,
      sub: sub || template.sub,
      photo: photoRef.current,
      qr: qrRef.current,
      // undefined lets the renderer place it exactly as the preview did.
      qrRect: qrRect || undefined,
    })

    out.toBlob(blob => {
      if (!blob) {
        setStatus({ kind: "error", text: "The browser would not produce the image." })
        return
      }
      const url = URL.createObjectURL(blob)
      const a = document.createElement("a")
      a.href = url
      a.download = `fcs-${template.id}-${trade.slug}${code ? `-${code}` : ""}.png`
      a.click()
      setTimeout(() => URL.revokeObjectURL(url), 2000)
      setStatus({ kind: "ok", text: "Downloaded. Drop it straight into the group." })
    }, "image/png")
  }

  /* The same link as text, for the caption under the image. */
  const copyLink = async () => {
    try {
      await navigator.clipboard.writeText(link)
      setStatus({ kind: "ok", text: "Link copied — paste it under the image." })
    } catch {
      setStatus({ kind: "error", text: "Could not copy — select the link above instead." })
    }
  }

  /* ── Register the id — MTC-FCS-041 ─────────────────────────────────── */
  const register = async () => {
    if (!code.trim()) {
      setStatus({ kind: "error", text: "Give the code a name first." })
      return
    }
    setStatus({ kind: "busy", text: "Saving the code…" })
    try {
      /* The session goes with it — FCS-070. The function takes the owner
         from the token and ignores any `affiliate` in the body, because a
         code is what somebody gets PAID against and a body that names its
         own owner is a body that can name somebody else's. */
      const { data: sessionData } = await supabase().auth.getSession()
      const token = sessionData?.session?.access_token

      const res = await fetch(apiUrl("affiliate-link"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: JSON.stringify({
          code: code.trim(),
          placedIn,
          template: template.id,
          trade: trade.slug,
          size: size.id,
          url: link,
        }),
      })
      const body = await res.json().catch(() => ({}))
      setStatus(
        res.ok
          ? {
              kind: user?.email ? "ok" : "error",
              text: user?.email
                ? body.message || "Saved. Clicks on this code will be tracked."
                : `${body.message} You are not logged in, so this code is not attached to anybody — log in and save it again to see it in your report.`,
            }
          : { kind: "error", text: body.message || `Could not save it (HTTP ${res.status}).` }
      )
    } catch (err) {
      setStatus({ kind: "error", text: `Could not save it: ${err.message}` })
    }
  }

  return (
    <div className={s.layout}>
      <div>
        <div className={s.panel}>
          <h2 className={s.panelTitle}>Your tracking code</h2>
          <div className={s.field}>
            <label htmlFor="ad-code">Code</label>
            <input
              id="ad-code"
              value={code}
              onChange={e => setCode(e.target.value.replace(/[^A-Za-z0-9_-]/g, ""))}
              placeholder="roof-grp-04"
              autoComplete="off"
            />
            <p className={s.hint}>
              Letters, numbers and dashes. Use a different one per group, so the report can
              tell you which group actually worked.
            </p>
          </div>
          <div className={s.field}>
            <label htmlFor="ad-group">Where you will post it</label>
            <input
              id="ad-group"
              value={placedIn}
              onChange={e => setPlacedIn(e.target.value)}
              placeholder="Denver Roofers (18k members)"
              autoComplete="off"
            />
          </div>
          <div className={s.linkOut}>{link}</div>
          <div className={s.bar}>
            <button type="button" className={s.button} onClick={makeQr}>
              Make the QR
            </button>
            <button type="button" className={`${s.button} ${s.ghost}`} onClick={register}>
              Save code
            </button>
            <button type="button" className={`${s.button} ${s.ghost}`} onClick={copyLink}>
              Copy link
            </button>
          </div>
        </div>

        <div className={s.panel}>
          <h2 className={s.panelTitle}>Template</h2>
          <div className={s.choices}>
            {AD_TEMPLATES.map(t => (
              <button
                key={t.id}
                type="button"
                className={s.choice}
                aria-pressed={t.id === templateId}
                onClick={() => setTemplateId(t.id)}
              >
                <span>
                  <span className={s.choiceName}>{t.name}</span>
                  <span className={s.choiceNote}>{fill(t.hook, { trade: trade.word })}</span>
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* ── COLOUR THEME — FCS-069 ────────────────────────────────────
            The same six the website builder offers, shown as their actual
            colours: nobody picks a palette from its name. */}
        <div className={s.panel}>
          <p className={s.panelTitle}>Colour theme</p>
          <div className={s.choices}>
            {THEMES.map(t => (
              <button
                key={t.id}
                type="button"
                className={s.choice}
                aria-pressed={t.id === themeId}
                onClick={() => setThemeId(t.id)}
              >
                <span>
                  <span className={s.swatches} aria-hidden="true">
                    <span style={{ background: t.primary }} />
                    <span style={{ background: t.accent }} />
                    <span style={{ background: t.ink }} />
                  </span>
                  <span className={s.choiceName}>{t.label}</span>
                  <span className={s.choiceNote}>{t.blurb}</span>
                </span>
              </button>
            ))}
          </div>
        </div>

        <div className={s.panel}>
          <h2 className={s.panelTitle}>Size</h2>
          <div className={s.choices}>
            {AD_SIZES.map(option => (
              <button
                key={option.id}
                type="button"
                className={s.choice}
                aria-pressed={option.id === sizeId}
                onClick={() => setSizeId(option.id)}
              >
                <span>
                  <span className={s.choiceName}>
                    {option.label} — {option.width}×{option.height}
                  </span>
                  <span className={s.choiceNote}>{option.note}</span>
                </span>
              </button>
            ))}
          </div>
        </div>

        <div className={s.panel}>
          <h2 className={s.panelTitle}>Words</h2>
          <div className={s.field}>
            <label htmlFor="ad-trade">Trade</label>
            <select id="ad-trade" value={tradeSlug} onChange={e => setTradeSlug(e.target.value)}>
              {AD_TRADES.map(t => (
                <option key={t.slug} value={t.slug}>
                  {t.word}
                </option>
              ))}
            </select>
          </div>
          <div className={s.field}>
            <label htmlFor="ad-price">Hosting price on the image</label>
            <select id="ad-price" value={price} onChange={e => setPrice(e.target.value)}>
              {PRICE_OPTIONS.map(p => (
                <option key={p} value={p}>
                  {p} / month
                </option>
              ))}
            </select>
          </div>
          <div className={s.field}>
            <label htmlFor="ad-headline">Headline</label>
            <textarea
              id="ad-headline"
              value={headline}
              onChange={e => setHeadline(e.target.value)}
              placeholder={template.headline}
            />
            <p className={s.hint}>A line break here is a line break on the image.</p>
          </div>
          <div className={s.field}>
            <label htmlFor="ad-sub">Sub-line</label>
            <textarea
              id="ad-sub"
              value={sub}
              onChange={e => setSub(e.target.value)}
              placeholder={template.sub}
            />
          </div>
        </div>
      </div>

      <div className={s.stage}>
        <div className={s.canvasWrap}>
          <canvas
            ref={canvasRef}
            className={`${s.canvas} ${dragging ? s.dragging : ""}`}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
          />
        </div>

        <div className={s.bar}>
          <div className={s.sizeRow} style={{ minWidth: 200 }}>
            <label htmlFor="ad-qr-size" className={s.status}>
              QR size
            </label>
            <input
              id="ad-qr-size"
              type="range"
              min="0.7"
              max="1.6"
              step="0.05"
              value={qrScale}
              onChange={e => resize(e.target.value)}
            />
          </div>
          <button
            type="button"
            className={`${s.button} ${s.ghost}`}
            onClick={() => {
              setQrRect(null)
              setQrScale(1)
            }}
          >
            Reset position
          </button>
          <span className={s.spacer} />
          <button type="button" className={s.button} onClick={download}>
            Download PNG
          </button>
        </div>

        <p className={s.status}>
          {status ? (
            <span className={status.kind === "error" ? s.error : status.kind === "ok" ? s.ok : ""}>
              {status.text}
            </span>
          ) : qrRef.current ? (
            "Drag the code to move it. The dashed outline is only on this preview."
          ) : (
            "The slot is empty until you make a QR — type a code and press Make the QR."
          )}
        </p>
      </div>
    </div>
  )
}

export default AdStudio
