import { AD_COLOURS, QR_SLOT, fill } from "./ad-templates"

/**
 * The palette this render is using — FCS-069.
 *
 * Module-level and reassigned at the top of drawAd, rather than threaded
 * through thirty call sites in the drawing helpers. Safe because a render is
 * one synchronous pass: nothing yields between setting this and finishing the
 * image, so two ads cannot be half-drawn in each other's colours.
 */
let ACTIVE = AD_COLOURS

/**
 * Drawing one advert — MTC-FCS-037 / 040.
 * ============================================================================
 * Pure canvas work, kept out of the component on purpose: the PREVIEW and the
 * EXPORT must be the same drawing. The studio adds selection handles on top of
 * the preview only, so nothing a marketer used to position the QR ends up
 * branded onto the image they post.
 *
 *     drawAd(ctx, spec)   background, words, price panel, CTA, QR
 *     ctx is 1080 wide; every measurement below is a fraction of that
 *
 * ── EVERYTHING SCALES FROM THE WIDTH ───────────────────────────────────────
 * `u` is one unit: canvas width ÷ 1080. Hard-coding pixel sizes would mean two
 * layouts to keep in step the moment a second canvas size exists, and there
 * are already two (4:5 and 1:1).
 */

/** Rounded rectangle path — older Safari has no roundRect. */
function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2)
  ctx.beginPath()
  ctx.moveTo(x + radius, y)
  ctx.arcTo(x + w, y, x + w, y + h, radius)
  ctx.arcTo(x + w, y + h, x, y + h, radius)
  ctx.arcTo(x, y + h, x, y, radius)
  ctx.arcTo(x, y, x + w, y, radius)
  ctx.closePath()
}

/** Wraps text to a width and returns the lines. `\n` is honoured as a break. */
function wrap(ctx, text, maxWidth) {
  const out = []
  for (const paragraph of String(text || "").split("\n")) {
    let line = ""
    for (const word of paragraph.split(/\s+/).filter(Boolean)) {
      const next = line ? `${line} ${word}` : word
      if (ctx.measureText(next).width <= maxWidth || !line) {
        line = next
      } else {
        out.push(line)
        line = word
      }
    }
    out.push(line)
  }
  return out
}

/**
 * Draws a line where ONE word is a different colour.
 *
 * The reference ad gets its punch from "GET A **FREE WEBSITE**", and a headline
 * in one flat colour reads as a notice rather than an offer.
 */
function drawSplitLine(ctx, line, x, y, highlight, base, accent) {
  const words = line.split(" ")
  let cursor = x
  for (let i = 0; i < words.length; i++) {
    const word = words[i]
    const isHot = highlight.includes(word.replace(/[^A-Z$0-9]/gi, "").toUpperCase())
    ctx.fillStyle = isHot ? accent : base
    ctx.fillText(word, cursor, y)
    cursor += ctx.measureText(`${word} `).width
  }
}

/** The roof glyph, drawn rather than loaded — one less asset to ship. */
function drawMark(ctx, x, y, size, colour) {
  ctx.save()
  ctx.fillStyle = colour
  ctx.beginPath()
  ctx.moveTo(x, y + size * 0.62)
  ctx.lineTo(x + size * 0.5, y + size * 0.12)
  ctx.lineTo(x + size, y + size * 0.62)
  ctx.lineTo(x + size * 0.84, y + size * 0.62)
  ctx.lineTo(x + size * 0.5, y + size * 0.3)
  ctx.lineTo(x + size * 0.16, y + size * 0.62)
  ctx.closePath()
  ctx.fill()
  ctx.fillRect(x + size * 0.28, y + size * 0.62, size * 0.18, size * 0.2)
  ctx.fillRect(x + size * 0.54, y + size * 0.62, size * 0.18, size * 0.2)
  ctx.restore()
}

/** A filled circle with a small white glyph, for the benefit list. */
function drawBullet(ctx, x, y, r, colour) {
  ctx.save()
  ctx.fillStyle = colour
  ctx.beginPath()
  ctx.arc(x + r, y + r, r, 0, Math.PI * 2)
  ctx.fill()
  ctx.strokeStyle = "#ffffff"
  ctx.lineWidth = r * 0.22
  ctx.lineCap = "round"
  ctx.lineJoin = "round"
  ctx.beginPath()
  ctx.moveTo(x + r * 0.58, y + r * 1.02)
  ctx.lineTo(x + r * 0.88, y + r * 1.34)
  ctx.lineTo(x + r * 1.44, y + r * 0.68)
  ctx.stroke()
  ctx.restore()
}

/** Where the QR sits by default, in canvas pixels. */
export function defaultQrRect(width, height) {
  const v = height / 1350
  const size = Math.max(width * QR_SLOT.size, QR_SLOT.minPixels * v)
  return {
    // Right column, below the price panel and above the call to action. Those
    // three blocks are the layout's only fixed points, so the slot is measured
    // from them rather than from the corner.
    x: width - size - width * QR_SLOT.right,
    y: height - size - height * QR_SLOT.bottom,
    size,
  }
}

/**
 * Draws the whole advert.
 *
 * @param {CanvasRenderingContext2D} ctx
 * @param {object} spec
 *   template, size, trade, price, headline, sub  — the words
 *   photo      an HTMLImageElement, or null
 *   qr         an HTMLImageElement, or null — null leaves the slot EMPTY,
 *              which is the state the brief asked for (MTC-FCS-037)
 *   qrRect     { x, y, size } in canvas pixels
 */
export function drawAd(ctx, spec) {
  // The chosen theme, or the house colours when nothing was chosen.
  ACTIVE = spec.colours || AD_COLOURS

  const { template, size, trade = "Contractor", price = "$15", photo = null, qr = null } = spec
  const W = size.width
  const H = size.height
  const words = { trade, price }

  /* Two units, and the smaller one wins for anything that eats vertical space.
     `u` is the horizontal unit (width ÷ 1080) and `v` the vertical one
     (height ÷ 1350, the tallest canvas). On a square canvas v is 0.8, so type
     and rhythm shrink together and the same layout still fits — which is the
     whole reason the two sizes can share one drawing. */
  const u = W / 1080
  const v = H / 1350
  const k = Math.min(u, v)

  const font = (weight, px, family = "Poppins") =>
    `${weight} ${Math.round(px * k)}px ${family}, "Segoe UI", Arial, sans-serif`

  const margin = W * 0.052
  const leftW = W * 0.44
  const rightX = W * 0.5
  const rightW = W - margin - rightX

  /* ── Ground ─────────────────────────────────────────────────────────── */
  ctx.fillStyle = ACTIVE.paper
  ctx.fillRect(0, 0, W, H)

  const wash = ctx.createLinearGradient(W * 0.45, 0, W, H * 0.4)
  wash.addColorStop(0, "#ffffff")
  wash.addColorStop(1, ACTIVE.haze)
  ctx.fillStyle = wash
  ctx.fillRect(W * 0.42, 0, W * 0.58, H * 0.34)

  /* ── Photograph, top right, feathered into the page ─────────────────── */
  if (photo) {
    const boxW = W * 0.5
    const boxH = H * 0.24
    const boxX = W - boxW
    const scale = Math.max(boxW / photo.naturalWidth, boxH / photo.naturalHeight)
    const drawW = photo.naturalWidth * scale
    const drawH = photo.naturalHeight * scale

    ctx.save()
    ctx.beginPath()
    ctx.rect(boxX, 0, boxW, boxH)
    ctx.clip()
    ctx.drawImage(photo, boxX + (boxW - drawW) / 2, (boxH - drawH) / 2, drawW, drawH)

    const fadeX = ctx.createLinearGradient(boxX, 0, boxX + boxW * 0.4, 0)
    fadeX.addColorStop(0, "rgba(255,255,255,1)")
    fadeX.addColorStop(1, "rgba(255,255,255,0)")
    ctx.fillStyle = fadeX
    ctx.fillRect(boxX, 0, boxW, boxH)

    const fadeY = ctx.createLinearGradient(0, boxH * 0.55, 0, boxH)
    fadeY.addColorStop(0, "rgba(255,255,255,0)")
    fadeY.addColorStop(1, "rgba(255,255,255,1)")
    ctx.fillStyle = fadeY
    ctx.fillRect(boxX, 0, boxW, boxH)
    ctx.restore()
  }

  ctx.textBaseline = "alphabetic"

  /* ── Mark ───────────────────────────────────────────────────────────── */
  drawMark(ctx, margin, H * 0.035, 66 * k, ACTIVE.navy)

  /* ── Headline ───────────────────────────────────────────────────────── */
  const headlineSize = 74
  const headlineLead = 84
  ctx.font = font(800, headlineSize)
  const headlineLines = wrap(
    ctx,
    fill(spec.headline || template.headline, words),
    W - margin * 2
  ).slice(0, 3)

  let y = H * 0.112
  for (const line of headlineLines) {
    y += headlineLead * k
    drawSplitLine(
      ctx,
      line,
      margin,
      y,
      ["FREE", "WEBSITE", "QUOTES", "MORE"],
      ACTIVE.navy,
      ACTIVE.orange
    )
  }

  /* ── Hook pill ──────────────────────────────────────────────────────── */
  y += 30 * k
  ctx.font = font(600, 31)
  const hook = fill(template.hook, words)
  const hookH = 60 * k
  const hookW = Math.min(ctx.measureText(hook).width + 52 * k, W - margin * 2)
  ctx.fillStyle = ACTIVE.navy
  roundRect(ctx, margin, y, hookW, hookH, 11 * k)
  ctx.fill()
  ctx.fillStyle = "#ffffff"
  ctx.fillText(hook, margin + 26 * k, y + hookH * 0.68)
  y += hookH + 32 * k

  /* ── Sub line ───────────────────────────────────────────────────────── */
  ctx.font = font(500, 34)
  const subLines = wrap(ctx, fill(spec.sub || template.sub, words), leftW + W * 0.06).slice(0, 3)
  for (const line of subLines) {
    y += 44 * k
    drawSplitLine(ctx, line, margin, y, ["FREE.", "FREE"], ACTIVE.ink, ACTIVE.orange)
  }

  /* ── The band below is two columns ──────────────────────────────────── */
  const bandTop = y + 40 * k

  /* Left: what you get. The list is trimmed to what the canvas can hold
     rather than drawn over the call to action — a benefit half-covered by an
     orange bar is worse than one left off. */
  const rowH = 52 * k
  const bulletR = 23 * k
  const ctaH = 138 * k
  const footH = Math.max(60 * k, H * 0.05)
  const ctaY = H - footH - ctaH - 26 * k
  const roomForRows = Math.floor((ctaY - 26 * k - bandTop) / rowH)

  const textX = margin + bulletR * 2 + 20 * k
  const textRoom = leftW - bulletR * 2 - 22 * k
  let rowY = bandTop
  for (const point of template.points.slice(0, Math.max(3, roomForRows))) {
    drawBullet(ctx, margin, rowY, bulletR, ACTIVE.navy)
    ctx.fillStyle = ACTIVE.ink
    const label = fill(point, words)

    /* Shrink to fit rather than wrap or truncate. A benefit on two lines
       breaks the rhythm of the list, and one cut off mid-word ("Your photos,
       logo &") looks like a bug to the person being sold to. */
    let px = 30
    ctx.font = font(500, px)
    while (ctx.measureText(label).width > textRoom && px > 21) {
      px -= 1
      ctx.font = font(500, px)
    }
    ctx.fillText(label, textX, rowY + bulletR * 1.45)
    rowY += rowH
  }

  /* Right: the price, then the QR under it. */
  const panelH = 152 * k
  const panelY = bandTop

  ctx.save()
  ctx.strokeStyle = ACTIVE.line
  ctx.lineWidth = 3 * k
  ctx.setLineDash([12 * k, 9 * k])
  roundRect(ctx, rightX, panelY, rightW, panelH, 12 * k)
  ctx.stroke()
  ctx.restore()

  ctx.textAlign = "center"
  const half = rightW / 2
  ctx.font = font(700, 24)
  ctx.fillStyle = ACTIVE.navy
  ctx.fillText(template.priceLead, rightX + half * 0.5, panelY + 42 * k)
  ctx.font = font(800, 72)
  ctx.fillStyle = ACTIVE.orange
  ctx.fillText(template.priceBig, rightX + half * 0.5, panelY + 116 * k)

  ctx.strokeStyle = ACTIVE.line
  ctx.lineWidth = 2 * k
  ctx.beginPath()
  ctx.moveTo(rightX + half, panelY + 20 * k)
  ctx.lineTo(rightX + half, panelY + panelH - 20 * k)
  ctx.stroke()

  ctx.font = font(700, 24)
  ctx.fillStyle = ACTIVE.navy
  ctx.fillText(template.priceRight, rightX + half * 1.5, panelY + 40 * k)
  ctx.font = font(800, 58)
  ctx.fillStyle = ACTIVE.orange
  ctx.fillText(fill(template.priceRightBig, words), rightX + half * 1.5, panelY + 96 * k)
  ctx.font = font(700, 20)
  ctx.fillStyle = ACTIVE.navy
  let suffixY = panelY + 118 * k
  for (const line of String(template.priceRightSuffix).split("\n")) {
    ctx.fillText(line, rightX + half * 1.5, suffixY)
    suffixY += 20 * k
  }

  /* The one-line reassurance, full width under both columns. */
  const noteH = 52 * k
  const noteY = ctaY - noteH - 22 * k
  ctx.fillStyle = ACTIVE.navy
  roundRect(ctx, margin, noteY, W - margin * 2, noteH, 9 * k)
  ctx.fill()
  ctx.font = font(600, 24)
  ctx.fillStyle = "#ffffff"
  ctx.fillText(template.priceNote, W / 2, noteY + noteH * 0.66)
  ctx.textAlign = "left"

  /* ── Call to action ─────────────────────────────────────────────────── */
  ctx.fillStyle = ACTIVE.orange
  roundRect(ctx, margin, ctaY, W - margin * 2, ctaH, 14 * k)
  ctx.fill()

  ctx.font = font(800, 40)
  ctx.fillStyle = "#ffffff"
  const ctaLines = String(template.cta).split("\n")
  let ctaTextY = ctaY + (ctaH - ctaLines.length * 48 * k) / 2 + 40 * k
  for (const line of ctaLines) {
    ctx.fillText(line, margin + 40 * k, ctaTextY)
    ctaTextY += 48 * k
  }

  /* ── Footer strip ───────────────────────────────────────────────────── */
  ctx.fillStyle = ACTIVE.navy
  ctx.fillRect(0, H - footH, W, footH)
  /* Shrunk until the longest label clears its slot with room to spare — a
     footer that touches the edge of the image reads as a crop. */
  const slot = W / template.footer.length
  let footPx = 21
  ctx.font = font(600, footPx)
  while (
    Math.max(...template.footer.map(l => ctx.measureText(l).width)) > slot - 26 * k &&
    footPx > 14
  ) {
    footPx -= 1
    ctx.font = font(600, footPx)
  }
  ctx.fillStyle = "#ffffff"
  ctx.textAlign = "center"
  template.footer.forEach((label, i) => {
    ctx.fillText(label, slot * i + slot / 2, H - footH / 2 + 8 * k)
  })
  ctx.textAlign = "left"

  /* ── The QR ─────────────────────────────────────────────────────────── */
  /* Placed by the layout, not by a fraction of the canvas. The gap between the
     price panel and the reassurance bar is different on a 4:5 and a 1:1 image,
     and a slot positioned by fractions lands on top of the price on one of
     them — which is exactly what it did before this was moved here. */
  const gapTop = panelY + panelH + 22 * k
  const gapBottom = noteY - 20 * k
  const wanted = Math.max(W * QR_SLOT.size, QR_SLOT.minPixels * Math.min(1, v))
  // 0.86 of the gap: the white card behind the code adds 7% padding on each
  // side, and a QR sized to the gap itself would put that card over the panel.
  const auto = Math.max(150 * k, Math.min(wanted, (gapBottom - gapTop) * 0.86, rightW))
  const qrRect = spec.qrRect || {
    size: auto,
    x: W - margin - auto,
    // Centred in the gap, so shrinking it does not leave it clinging to an edge.
    y: gapTop + Math.max(0, (gapBottom - gapTop - auto) / 2),
  }

  drawQrSlot(ctx, qrRect, qr, k)

  return { qrRect }
}

/**
 * The QR, or the empty slot that is waiting for one.
 *
 * The white card behind it is not decoration: a QR printed straight onto a
 * photograph or a coloured panel loses the quiet zone scanners need, and
 * "it only works sometimes" is the worst bug this tool could ship with.
 */
export function drawQrSlot(ctx, rect, qr, u = 1) {
  const pad = rect.size * 0.07
  ctx.save()

  ctx.shadowColor = "rgba(13, 35, 64, 0.22)"
  ctx.shadowBlur = 26 * u
  ctx.shadowOffsetY = 6 * u
  ctx.fillStyle = "#ffffff"
  roundRect(ctx, rect.x - pad, rect.y - pad, rect.size + pad * 2, rect.size + pad * 2, 14 * u)
  ctx.fill()
  ctx.shadowColor = "transparent"

  if (qr) {
    ctx.drawImage(qr, rect.x, rect.y, rect.size, rect.size)
  } else {
    // Empty on purpose — MTC-FCS-037.
    ctx.strokeStyle = ACTIVE.line
    ctx.lineWidth = 3 * u
    ctx.setLineDash([14 * u, 10 * u])
    roundRect(ctx, rect.x, rect.y, rect.size, rect.size, 8 * u)
    ctx.stroke()
    ctx.setLineDash([])

    ctx.fillStyle = ACTIVE.muted
    ctx.font = `700 ${Math.round(24 * u)}px Poppins, Arial, sans-serif`
    ctx.textAlign = "center"
    ctx.fillText(QR_SLOT.label, rect.x + rect.size / 2, rect.y + rect.size / 2 + 8 * u)
    ctx.textAlign = "left"
  }

  ctx.restore()
}
