import * as React from "react"
import Header from "../components/Header"
import Seo from "../components/Seo"
import AdStudio from "../components/ads/AdStudio"
import { useAuth } from "../context/auth"
import { AFFILIATE_MESSAGES, affiliateFor } from "../lib/affiliate"
import * as s from "../components/ads/AdStudio.module.css"

/**
 * The ad studio — MTC-FCS-037 / 040 / 041.
 *
 * For the marketers dropping images into Facebook groups, not for customers.
 * `noindex`, because an internal tool in search results is a support question
 * waiting to happen — and the page is useless without a tracking code anyway.
 */
const AdStudioPage = () => {
  /* ── APPROVED MARKETERS ONLY — MTC-FCS-037..041 ───────────────────────
     This page mints tracking codes that somebody gets PAID against, so it
     is not open to anybody who happens to have an account. An affiliate is
     a separate, approved person from a contractor; see lib/affiliate.js. */
  const { user, ready } = useAuth()
  const [role, setRole] = React.useState({ status: "checking", affiliate: null })

  React.useEffect(() => {
    if (!ready) return
    if (!user) {
      setRole({ status: "anonymous", affiliate: null })
      return
    }
    affiliateFor(user).then(setRole)
  }, [ready, user])

  /* Same rule as /affiliate: show nothing that implies an answer until the
     session says who this is. Rendering the studio while the check is in
     flight let a stranger see — and start typing into — a tool that mints
     tracking codes somebody gets paid against. */
  if (!ready || role.status === "checking") {
    return (
      <>
        <Header />
        <main className={s.page} data-print="hide">
          <div className="container">
            <div className={s.head}>
              <h1 className={s.title}>Ad studio</h1>
              <p className={s.lead}>Loading…</p>
            </div>
          </div>
        </main>
      </>
    )
  }

  if (ready && role.status !== "active") {
    const message = AFFILIATE_MESSAGES[role.status] || AFFILIATE_MESSAGES.unknown
    return (
      <>
        <Header />
        <main className={s.page} data-print="hide">
          <div className="container">
            <div className={s.head}>
              <h1 className={s.title}>{message.title}</h1>
              <p className={s.lead}>{message.body}</p>
            </div>
          </div>
        </main>
      </>
    )
  }

  return (
    <>
      <Header />
      <main className={s.page} data-print="hide">
        <div className="container">
          <div className={s.head}>
            <h1 className={s.title}>Ad studio</h1>
            <p className={s.lead}>
              Make an image for a Facebook group, with your own tracking code in the QR. Every scan
              lands on <strong>/website?id=your-code</strong>, so you can see which groups and which
              wording actually brought people in.
            </p>
          </div>
          <AdStudio styles={s} />
        </div>
      </main>
    </>
  )
}

export const Head = () => (
  <Seo title="Ad studio" description="Make a trackable advert for a Facebook group." noindex />
)

export default AdStudioPage
