/**
 * The ad's colours, from the same six themes the website builder offers —
 * FCS-069.
 *
 * A marketer posting into six different groups wants six different-looking
 * images; an identical advert six times reads as spam and gets the poster
 * removed. These are the builder's own palettes rather than a second set, so
 * an ad and the website it sells look like the same company.
 *
 * `navy` is the theme's ink (headings, dark bands), `orange` its accent (the
 * price, the call to action). The three greys stay put: they are paper and
 * rules, and tinting those just makes an advert look dirty.
 */
export function adPalette(themeId) {
  const theme = THEMES.find(t => t.id === themeId)
  if (!theme) return AD_COLOURS
  return {
    ...AD_COLOURS,
    navy: theme.ink,
    ink: theme.primary,
    orange: theme.accent,
  }
}

