/**
 * Where the QR goes, as a fraction of the canvas.
 *
 * Fractions rather than pixels so one layout serves both sizes, and bottom-
 * right because that is where a thumb is already resting on a phone — and
 * because it keeps the code clear of the headline if the image is cropped
 * square from the top.
 */
export const QR_SLOT = {
  // Of the canvas width.
  size: 0.23,
  right: 0.055,
  bottom: 0.235,
  /** Never smaller than this, whatever the canvas — see the note above. */
  minPixels: 240,
  label: "QR CODE",
  hint: "SCAN ME",
}

