/** Fills {TRADE} / {trade} / {Trade} / {PRICE} in any of the strings above. */
export function fill(text, { trade = "Contractor", price = "$15" } = {}) {
  return String(text || "")
    .replace(/\{TRADE\}/g, trade.toUpperCase())
    .replace(/\{Trade\}/g, trade)
    .replace(/\{trade\}/g, trade.toLowerCase())
    .replace(/\{PRICE\}/g, price)
}

/** One template by id, or the first — never undefined. */
export function templateById(id) {
  return AD_TEMPLATES.find(t => t.id === id) || AD_TEMPLATES[0]
}

/** One size by id, or the portrait default. */
export function sizeById(id) {
  return AD_SIZES.find(s => s.id === id) || AD_SIZES[0]
}

/**
 * The link a QR points at — MTC-FCS-038.
 *
 * `/website?id=<code>` exactly as the brief specifies, so the landing page can
 * record which image and which group produced the visit.
 */
export function trackedUrl(origin, code) {
  const base = String(origin || "https://freecontractorservices.com").replace(/\/+$/, "")
  const clean = String(code || "").replace(/[^A-Za-z0-9_-]/g, "")
  return clean ? `${base}/website?id=${clean}` : `${base}/website`
}
